4	use std::env;
5	use std::sync::Arc;
6	use std::sync::LazyLock;
7	use std::time::Duration;
8	
9	use async_stream::stream;
10	use async_trait::async_trait;
11	
12	use dynamo_runtime::engine::{AsyncEngine, AsyncEngineContextProvider, ResponseStream};
13	use dynamo_runtime::error::{DynamoError, ErrorType};
14	#[cfg(test)]
15	use dynamo_runtime::pipeline::RequestStream;
16	use dynamo_runtime::pipeline::{Error, ManyIn, ManyOut, SingleIn};
17	use dynamo_runtime::protocols::annotated::Annotated;
18	use futures::StreamExt;
19	
20	use crate::protocols::openai::{
21	    chat_completions::{NvCreateChatCompletionRequest, NvCreateChatCompletionStreamResponse},
22	    completions::{NvCreateCompletionRequest, NvCreateCompletionResponse, prompt_to_string},
23	};
24	use crate::types::openai::embeddings::NvCreateEmbeddingRequest;
25	use crate::types::openai::embeddings::NvCreateEmbeddingResponse;
26	use dynamo_protocols::types::realtime::{
27	    EventType, MaxOutputTokens, RealtimeAPIError, RealtimeClientEvent, RealtimeResponse,
28	    RealtimeResponseStatus, RealtimeServerEvent, RealtimeServerEventError,
29	    RealtimeServerEventResponseAudioDelta, RealtimeServerEventResponseAudioDone,
30	    RealtimeServerEventResponseCreated, RealtimeServerEventResponseDone,
31	    RealtimeServerEventSessionUpdated,
32	};
33	
34	//
35	// The engines are each in their own crate under `lib/engines`
36	//
37	
38	#[derive(Debug, Clone)]
39	pub struct MultiNodeConfig {
40	    /// How many nodes / hosts we are using
41	    pub num_nodes: u32,
42	    /// Unique consecutive integer to identify this node
43	    pub node_rank: u32,
44	    /// host:port of head / control node
45	    pub leader_addr: String,
46	}
47	
48	impl Default for MultiNodeConfig {
49	    fn default() -> Self {
50	        MultiNodeConfig {
51	            num_nodes: 1,
52	            node_rank: 0,
53	            leader_addr: "".to_string(),
54	        }
55	    }
56	}
57	
58	//
59	// Example echo engines
60	//
61	
62	/// How long to sleep between echoed tokens.
63	/// Default is 10ms which gives us 100 tok/s.
64	/// Can be configured via the DYN_TOKEN_ECHO_DELAY_MS environment variable.
65	pub static TOKEN_ECHO_DELAY: LazyLock<Duration> = LazyLock::new(|| {
66	    const DEFAULT_DELAY_MS: u64 = 10;
67	
68	    let delay_ms = env::var("DYN_TOKEN_ECHO_DELAY_MS")
69	        .ok()
70	        .and_then(|val| val.parse::<u64>().ok())
71	        .unwrap_or(DEFAULT_DELAY_MS);
72	
73	    Duration::from_millis(delay_ms)
74	});
75	
76	/// Engine that accepts un-preprocessed requests and echos the prompt back as the response
77	/// Useful for testing ingress such as service-http.
78	struct EchoEngine {}
79	
80	/// Validate Engine that verifies request data
81	pub struct ValidateEngine<E> {
82	    inner: E,
83	}
84	
85	impl<E> ValidateEngine<E> {
86	    pub fn new(inner: E) -> Self {
87	        Self { inner }
88	    }
89	}
90	
91	/// Engine that dispatches requests to either OpenAICompletions
92	/// or OpenAIChatCompletions engine
93	pub struct EngineDispatcher<E> {
94	    inner: E,
95	}
96	
97	impl<E> EngineDispatcher<E> {
98	    pub fn new(inner: E) -> Self {
99	        EngineDispatcher { inner }
100	    }
101	}
102	
103	/// Trait on request types that allows us to validate the data
104	pub trait ValidateRequest {
105	    fn validate(&self) -> Result<(), anyhow::Error>;
106	}
107	
108	/// Trait that allows handling both completion and chat completions requests
109	#[async_trait]
110	pub trait StreamingEngine: Send + Sync {
111	    async fn handle_completion(
112	        &self,
113	        req: SingleIn<NvCreateCompletionRequest>,
114	    ) -> Result<ManyOut<Annotated<NvCreateCompletionResponse>>, Error>;
115	
116	    async fn handle_chat(
117	        &self,
118	        req: SingleIn<NvCreateChatCompletionRequest>,
119	    ) -> Result<ManyOut<Annotated<NvCreateChatCompletionStreamResponse>>, Error>;
120	}
121	
122	/// Trait that allows handling embedding requests
123	#[async_trait]
124	pub trait EmbeddingEngine: Send + Sync {
125	    async fn handle_embedding(
126	        &self,
127	        req: SingleIn<NvCreateEmbeddingRequest>,
128	    ) -> Result<ManyOut<Annotated<NvCreateEmbeddingResponse>>, Error>;
129	}
130	
131	pub fn make_echo_engine() -> Arc<dyn StreamingEngine> {
132	    let engine = EchoEngine {};
133	    let data = EngineDispatcher::new(engine);
134	    Arc::new(data)
135	}
136	
137	/// Per-delta chunk size for the echo engine's audio output, in UTF-8-aware bytes.
138	const ECHO_AUDIO_DELTA_CHUNK_LEN: usize = 64;
139	
140	/// Mock realtime engine for `/v1/realtime` end-to-end plumbing.
141	///
142	/// Echoes `session.update` and wraps `input_audio_buffer.append` in a
143	/// spec-shaped response envelope; rejects everything else as
144	/// `echo_engine_unsupported`. Unlike a real engine, the response envelope
145	/// is emitted immediately on append rather than gated on `response.create` —
146	/// the mock has no concept of turn-taking.
147	pub struct EchoBidirectionalEngine;
148	
149	#[async_trait]
150	impl AsyncEngine<ManyIn<RealtimeClientEvent>, ManyOut<Annotated<RealtimeServerEvent>>, Error>
151	    for EchoBidirectionalEngine
152	{
153	    async fn generate(
154	        &self,
155	        incoming: ManyIn<RealtimeClientEvent>,
156	    ) -> Result<ManyOut<Annotated<RealtimeServerEvent>>, Error> {
157	        let ctx = incoming.context();
158	        let session_id = ctx.id().to_string();
159	        let ctx_for_stream = ctx.clone();
160	        let (request_stream, _ctx_unit) = incoming.into_parts();
161	        let mut incoming = request_stream.take().ok_or_else(|| {
162	            anyhow::anyhow!("RequestStream::take called twice on bidirectional input")
163	        })?;
164	
165	        let output = stream! {
166	            let ctx = ctx_for_stream;
167	            let mut frame: u64 = 0;
168	
169	            while let Some(client_event) = incoming.next().await {
170	                if ctx.is_stopped() {
171	                    break;
172	                }
173	
174	                match client_event {
175	                    RealtimeClientEvent::SessionUpdate(req) => {
176	                        frame += 1;
177	                        yield annotated_event(
178	                            frame,
179	                            RealtimeServerEvent::SessionUpdated(
180	                                RealtimeServerEventSessionUpdated {
181	                                    event_id: format!("event_{session_id}_{frame}"),
182	                                    session: req.session,
183	                                },
184	                            ),
185	                        );
186	                    }
187	                    RealtimeClientEvent::InputAudioBufferAppend(req) => {
188	                        let response_id = format!("resp_{session_id}_{frame}");
189	                        let item_id = format!("item_{session_id}_{frame}");
190	
191	                        frame += 1;
192	                        yield annotated_event(
193	                            frame,
194	                            RealtimeServerEvent::ResponseCreated(
195	                                RealtimeServerEventResponseCreated {
196	                                    event_id: format!("event_{session_id}_{frame}"),
197	                                    response: echo_response(
198	                                        &response_id,
199	                                        RealtimeResponseStatus::InProgress,
200	                                    ),
201	                                },
202	                            ),
203	                        );
204	
205	                        // Slice the base64 audio in-place on UTF-8 char
206	                        // boundaries — avoids the O(N) `Vec<char>` an upfront
207	                        // `chars().collect()` would allocate on a 15 MB frame.
208	                        let audio = req.audio.as_str();
209	                        let mut start = 0;
210	                        while start < audio.len() {
211	                            if ctx.is_stopped() {
212	                                break;
213	                            }
214	                            let mut end = (start + ECHO_AUDIO_DELTA_CHUNK_LEN).min(audio.len());
215	                            while !audio.is_char_boundary(end) {
216	                                end -= 1;
217	                            }
218	                            frame += 1;
219	                            yield annotated_event(
220	                                frame,
221	                                RealtimeServerEvent::ResponseOutputAudioDelta(
222	                                    RealtimeServerEventResponseAudioDelta {
223	                                        event_id: format!("event_{session_id}_{frame}"),
224	                                        response_id: response_id.clone(),
225	                                        item_id: item_id.clone(),
226	                                        output_index: 0,
227	                                        content_index: 0,
228	                                        delta: audio[start..end].to_string(),
229	                                    },
230	                                ),
231	                            );
232	                            start = end;
233	                        }
234	                        if ctx.is_stopped() {
235	                            break;
236	                        }
237	                        frame += 1;
238	                        yield annotated_event(
239	                            frame,
240	                            RealtimeServerEvent::ResponseOutputAudioDone(
241	                                RealtimeServerEventResponseAudioDone {
242	                                    event_id: format!("event_{session_id}_{frame}"),
243	                                    response_id: response_id.clone(),
244	                                    item_id: item_id.clone(),
245	                                    output_index: 0,
246	                                    content_index: 0,
247	                                },
248	                            ),
249	                        );
250	                        frame += 1;
251	                        yield annotated_event(
252	                            frame,
253	                            RealtimeServerEvent::ResponseDone(
254	                                RealtimeServerEventResponseDone {
255	                                    event_id: format!("event_{session_id}_{frame}"),
256	                                    response: echo_response(
257	                                        &response_id,
258	                                        RealtimeResponseStatus::Completed,
259	                                    ),
260	                                },
261	                            ),
262	                        );
263	                    }
264	                    other => {
265	                        frame += 1;
266	                        yield annotated_event(
267	                            frame,
268	                            RealtimeServerEvent::Error(RealtimeServerEventError {
269	                                event_id: format!("event_{session_id}_{frame}"),
270	                                error: RealtimeAPIError {
271	                                    r#type: "invalid_request_error".to_string(),
272	                                    code: Some("echo_engine_unsupported".to_string()),
273	                                    message: format!(
274	                                        "echo engine does not support client event {}",
275	                                        other.event_type()
276	                                    ),
277	                                    param: None,
278	                                    event_id: None,
279	                                },
280	                            }),
281	                        );
282	                    }
283	                }
284	            }
285	        };
286	
287	        Ok(ResponseStream::new(Box::pin(output), ctx))
288	    }
289	}
290	
291	fn annotated_event(frame: u64, event: RealtimeServerEvent) -> Annotated<RealtimeServerEvent> {
292	    Annotated {
293	        id: Some(frame.to_string()),
294	        ..Annotated::from_data(event)
295	    }
296	}
297	
298	/// Minimal `RealtimeResponse` payload for the echo engine's `response.created`
299	/// and `response.done` envelope frames. Real engines populate `output`,
300	/// `usage`, etc.; the mock leaves them empty so the spec shape is intact
301	/// without pretending to have generated tokens.
302	fn echo_response(id: &str, status: RealtimeResponseStatus) -> RealtimeResponse {
303	    RealtimeResponse {
304	        audio: None,
305	        conversation_id: None,
306	        id: id.to_string(),
307	        max_output_tokens: MaxOutputTokens::Inf,
308	        metadata: None,
309	        object: "realtime.response".to_string(),
310	        output: Vec::new(),
311	        output_modalities: vec!["audio".to_string()],
312	        status,
313	        status_details: None,
314	        usage: None,
315	    }
316	}
317	
318	#[async_trait]
319	impl
320	    AsyncEngine<
321	        SingleIn<NvCreateChatCompletionRequest>,
322	        ManyOut<Annotated<NvCreateChatCompletionStreamResponse>>,
323	        Error,
324	    > for EchoEngine
325	{
326	    async fn generate(
327	        &self,
328	        incoming_request: SingleIn<NvCreateChatCompletionRequest>,
329	    ) -> Result<ManyOut<Annotated<NvCreateChatCompletionStreamResponse>>, Error> {
330	        let (request, context) = incoming_request.transfer(());
331	        let ctx = context.context();
332	        let mut deltas = request.response_generator(ctx.id().to_string());
333	        let Some(req) = request.inner.messages.into_iter().next_back() else {
334	            anyhow::bail!("Empty chat messages in request");
335	        };
336	
337	        let prompt = match req {
338	            dynamo_protocols::types::ChatCompletionRequestMessage::User(user_msg) => {
339	                match user_msg.content {
340	                    dynamo_protocols::types::ChatCompletionRequestUserMessageContent::Text(
341	                        prompt,
342	                    ) => prompt,
343	                    _ => anyhow::bail!("Invalid request content field, expected Content::Text"),
344	                }
345	            }
346	            _ => anyhow::bail!("Invalid request type, expected User message"),
347	        };
348	
349	        let output = stream! {
350	            let mut id = 1;
351	            for c in prompt.chars() {
352	                // we are returning characters not tokens, so there will be some postprocessing overhead
353	                tokio::time::sleep(*TOKEN_ECHO_DELAY).await;
354	                let response = deltas.create_choice(0, Some(c.to_string()), None, None);
355	                yield Annotated{ id: Some(id.to_string()), data: Some(response), event: None, comment: None, error: None };
356	                id += 1;
357	            }
358	
359	            let response =
360	                deltas.create_choice(0, None, Some(dynamo_protocols::types::FinishReason::Stop), None);
361	            yield Annotated { id: Some(id.to_string()), data: Some(response), event: None, comment: None, error: None };
362	        };
363	
364	        Ok(ResponseStream::new(Box::pin(output), ctx))
365	    }
366	}
367	
368	#[async_trait]
369	impl
370	    AsyncEngine<
371	        SingleIn<NvCreateCompletionRequest>,
372	        ManyOut<Annotated<NvCreateCompletionResponse>>,
373	        Error,
374	    > for EchoEngine
375	{
376	    async fn generate(
377	        &self,
378	        incoming_request: SingleIn<NvCreateCompletionRequest>,
379	    ) -> Result<ManyOut<Annotated<NvCreateCompletionResponse>>, Error> {
380	        let (request, context) = incoming_request.transfer(());
381	        let ctx = context.context();
382	        let deltas = request.response_generator(ctx.id().to_string());
383	        let chars_string = prompt_to_string(&request.inner.prompt);
384	        let output = stream! {
385	            let mut id = 1;
386	            for c in chars_string.chars() {
387	                tokio::time::sleep(*TOKEN_ECHO_DELAY).await;
388	                let response = deltas.create_choice(0, Some(c.to_string()), None, None);
389	                yield Annotated{ id: Some(id.to_string()), data: Some(response), event: None, comment: None, error: None };
390	                id += 1;
391	            }
392	            let response = deltas.create_choice(
393	                0,
394	                None,
395	                Some(dynamo_protocols::types::CompletionFinishReason::Stop),
396	                None,
397	            );
398	            yield Annotated { id: Some(id.to_string()), data: Some(response), event: None, comment: None, error: None };
399	
400	        };
401	
402	        Ok(ResponseStream::new(Box::pin(output), ctx))
403	    }
404	}
405	
406	#[async_trait]
407	impl
408	    AsyncEngine<
409	        SingleIn<NvCreateEmbeddingRequest>,
410	        ManyOut<Annotated<NvCreateEmbeddingResponse>>,
