726	#[pyo3(signature = (distributed_runtime, args))]
727	pub fn make_engine<'p>(
728	    py: Python<'p>,
729	    distributed_runtime: super::DistributedRuntime,
730	    args: EntrypointArgs,
731	) -> PyResult<Bound<'p, PyAny>> {
732	    let mut builder = LocalModelBuilder::default();
733	    builder
734	        .model_name(
735	            args.model_name
736	                .clone()
737	                .or_else(|| args.model_path.clone().map(|p| p.display().to_string())),
738	        )
739	        .endpoint_id(args.endpoint_id.clone())
740	        .request_template(args.template_file.clone())
741	        .kv_cache_block_size(args.kv_cache_block_size)
742	        .router_config(args.router_config.clone().map(|rc| rc.into()))
743	        .migration_limit(Some(args.migration_limit))
744	        .migration_max_seq_len(args.migration_max_seq_len)
745	        .http_host(args.http_host.clone())
746	        .http_port(args.http_port)
747	        .http_metrics_port(args.http_metrics_port);
748	    if let Some(metrics_config) = args.metrics_config.clone() {
749	        builder.metrics_config(metrics_config);
750	    }
751	    if let Some(frontend_api_config) = args.frontend_api_config.clone() {
752	        builder.frontend_api_config(frontend_api_config);
753	    }
754	    builder
755	        .tls_cert_path(args.tls_cert_path.clone())
756	        .tls_key_path(args.tls_key_path.clone())
757	        .is_mocker(matches!(args.engine_type, EngineType::Mocker))
758	        .extra_engine_args(args.extra_engine_args.clone())
759	        .runtime_config(args.runtime_config.clone().inner)
760	        .namespace(args.namespace.clone())
761	        .namespace_prefix(args.namespace_prefix.clone());
762	    pyo3_async_runtimes::tokio::future_into_py(py, async move {
763	        if let Some(model_path) = args.model_path.clone() {
764	            let local_path = if model_path.exists() {
765	                model_path
766	            } else {
767	                // Mocker only needs tokenizer, not weights
768	                let ignore_weights = matches!(args.engine_type, EngineType::Mocker);
769	                // Preserve the original HF model ID as source_path so the
770	                // frontend can resolve model metadata even when the served
771	                // model name differs (e.g., --model-name model-1 --model-path
772	                // Qwen/Qwen3-0.6B).
773	                builder.source_path(model_path.clone());
774	                LocalModel::fetch(&model_path.display().to_string(), ignore_weights)
775	                    .await
776	                    .map_err(to_pyerr)?
777	            };
778	            builder.model_path(local_path);
779	        }
780	
781	        let local_model = builder.build().await.map_err(to_pyerr)?;
782	        let inner = select_engine(distributed_runtime, args, local_model)
783	            .await
784	            .map_err(to_pyerr)?;
785	        Ok(EngineConfig { inner })
786	    })
787	}
788	
789	/// Convert a PyEngineFactory to a Rust ChatEngineFactoryCallback
790	fn py_engine_factory_to_callback(factory: PyEngineFactory) -> ChatEngineFactoryCallback {
791	    let callback = factory.callback;
792	    let locals = factory.locals;
793	
794	    Arc::new(
795	        move |instance_id: RsModelCardInstanceId,
796	              card: RsModelDeploymentCard,
797	              routed_engine: PrefillRoutedEngine|
798	              -> Pin<
799	            Box<dyn Future<Output = anyhow::Result<OpenAIChatCompletionsStreamingEngine>> + Send>,
800	        > {
801	            let callback = callback.clone();
802	            let locals = locals.clone();
803	
804	            Box::pin(async move {
805	                // Acquire GIL to call Python callback and convert coroutine to future
806	                let py_future = Python::with_gil(|py| {
807	                    let py_instance_id =
808	                        Py::new(py, crate::ModelCardInstanceId { inner: instance_id }).map_err(
809	                            |e| anyhow::anyhow!("Failed to create Python ModelCardInstanceId: {e}"),
810	                        )?;
811	                    // Create Python ModelDeploymentCard wrapper
812	                    let py_card = ModelDeploymentCard { inner: card };
813	                    let py_card_obj = Py::new(py, py_card)
814	                        .map_err(|e| anyhow::anyhow!("Failed to create Python MDC: {e}"))?;
815	                    let py_routed = Py::new(
816	                        py,
817	                        crate::llm::routed_engine::RoutedEngine::new(routed_engine),
818	                    )
819	                    .map_err(|e| anyhow::anyhow!("Failed to create Python RoutedEngine: {e}"))?;
820	
821	                    // Call Python async function to get a coroutine
822	                    let coroutine = callback
823	                        .call1(py, (py_instance_id, py_card_obj, py_routed))
824	                        .map_err(|e| anyhow::anyhow!("Failed to call chat_engine_factory: {e}"))?;
825	
826	                    // Use the TaskLocals captured at registration time
827	                    pyo3_async_runtimes::into_future_with_locals(&locals, coroutine.into_bound(py))
828	                        .map_err(|e| anyhow::anyhow!("Failed to convert coroutine to future: {e}"))
829	                })?;
830	
831	                // Await the Python coroutine (GIL is released during await)
832	                let py_result = py_future
833	                    .await
834	                    .map_err(|e| anyhow::anyhow!("chat_engine_factory callback failed: {}", e))?;
835	
836	                // Extract PythonAsyncEngine from the Python result and wrap in Arc
837	                let engine: OpenAIChatCompletionsStreamingEngine = Python::with_gil(|py| {
838	                    let engine: PythonAsyncEngine = py_result.extract(py).map_err(|e| {
839	                        anyhow::anyhow!("Failed to extract PythonAsyncEngine: {}", e)
840	                    })?;
841	                    Ok::<_, anyhow::Error>(Arc::new(engine))
842	                })?;
843	
844	                Ok(engine)
845	            })
846	        },
847	    )
848	}
849	
850	async fn select_engine(
851	    #[allow(unused_variables)] distributed_runtime: super::DistributedRuntime,
852	    args: EntrypointArgs,
853	    local_model: LocalModel,
854	) -> anyhow::Result<RsEngineConfig> {
855	    let inner = match args.engine_type {
856	        EngineType::Echo => {
857	            // There is no validation for the echo engine
858	            RsEngineConfig::InProcessText {
859	                model: Box::new(local_model),
860	                engine: dynamo_llm::engines::make_echo_engine(),
861	            }
862	        }
863	        EngineType::Dynamic => {
864	            //  Convert Python chat engine factory to Rust callback
865	            let chat_engine_factory = args.chat_engine_factory.map(py_engine_factory_to_callback);
866	            let prefill_load_estimator = args
867	                .aic_perf_config
868	                .as_ref()
869	                .map(|config| {
870	                    Python::with_gil(|py| {
871	                        create_aic_prefill_load_estimator(
872	                            py,
873	                            config.backend_name(),
874	                            config.system(),
875	                            config.model_path(),
876	                            config.tp_size(),
877	                            config.backend_version(),
878	                            config.moe_tp_size(),
879	                            config.moe_ep_size(),
880	                            config.attention_dp_size(),
881	                            config.gemm_dtype(),
882	                            config.moe_dtype(),
883	                            config.fmha_dtype(),
884	                            config.kv_cache_dtype(),
885	                            config.comm_dtype(),
886	                            config.nextn(),
887	                            config.nextn_accept_rates(),
888	                        )
889	                    })
890	                })
891	                .transpose()?;
892	            RsEngineConfig::Dynamic {
893	                model: Box::new(local_model),
894	                chat_engine_factory,
895	                prefill_load_estimator,
896	            }
897	        }
898	        EngineType::Mocker => {
899	            let mut mocker_args = if let Some(mocker_engine_args) = args.mocker_engine_args {
900	                mocker_engine_args.inner()
901	            } else if let Some(extra_args_path) = args.extra_engine_args {
902	                RsMockEngineArgs::from_json_file(&extra_args_path).map_err(|e| {
903	                    anyhow::anyhow!(
904	                        "Failed to load mocker args from {:?}: {}",
905	                        extra_args_path,
906	                        e
907	                    )
908	                })?
909	            } else {
910	                tracing::warn!(
911	                    "No extra_engine_args specified for mocker engine. Using default mocker args."
912	                );
913	                RsMockEngineArgs::default()
914	            };
915	
916	            // If aic_backend is set, create Python AIC callback and override perf_model
917	            if let Some(ref backend_name) = mocker_args.aic_backend {
918	                let backend = backend_name.clone();
919	                let system = mocker_args.aic_system.as_deref().unwrap_or("h200_sxm");
920	                let model_name = mocker_args
921	                    .aic_model_path
922	                    .as_deref()
923	                    .unwrap_or_else(|| local_model.card().source_path());
924	                let backend_version = mocker_args.aic_backend_version.as_deref();
925	                let tp_size = mocker_args.aic_tp_size.unwrap_or(1);
926	                let moe_tp_size = mocker_args.aic_moe_tp_size;
927	                let moe_ep_size = mocker_args.aic_moe_ep_size;
928	                let attention_dp_size = mocker_args.aic_attention_dp_size;
929	                let gemm_dtype = mocker_args.aic_gemm_dtype.as_deref();
930	                let moe_dtype = mocker_args.aic_moe_dtype.as_deref();
931	                let fmha_dtype = mocker_args.aic_fmha_dtype.as_deref();
932	                let kv_cache_dtype = mocker_args.aic_kv_cache_dtype.as_deref();
933	                let comm_dtype = mocker_args.aic_comm_dtype.as_deref();
934	                let nextn = mocker_args.aic_nextn;
935	                let undiscounted_accept_rates = mocker_args.undiscounted_aic_accept_rates();
936	                match Python::with_gil(|py| {
937	                    create_aic_callback(
938	                        py,
939	                        &backend,
940	                        system,
941	                        model_name,
942	                        tp_size,
943	                        backend_version,
944	                        moe_tp_size,
945	                        moe_ep_size,
946	                        attention_dp_size,
947	                        gemm_dtype,
948	                        moe_dtype,
949	                        fmha_dtype,
950	                        kv_cache_dtype,
951	                        comm_dtype,
952	                        nextn,
953	                        undiscounted_accept_rates.as_deref(),
954	                    )
955	                }) {
956	                    Ok(callback) => {
957	                        tracing::info!(
958	                            "AIC perf model: backend={}, gpu={}, model={}, version={:?}",
959	                            backend,
960	                            system,
961	                            model_name,
962	                            backend_version
963	                        );
964	                        mocker_args.perf_model = Arc::new(PerfModel::from_aic_callback(callback));
965	                    }
966	                    Err(e) => {
967	                        return Err(anyhow::anyhow!(
968	                            "Failed to create AIC callback (--aic-perf-model was requested): {}",
969	                            e
970	                        ));
971	                    }
972	                }
973	            }
974	
975	            let endpoint = local_model.endpoint_id().clone();
976	
977	            let engine =
978	                make_mocker_engine(distributed_runtime.inner, endpoint, mocker_args).await?;
979	
980	            RsEngineConfig::InProcessTokens {
981	                engine,
982	                model: Box::new(local_model),
983	                is_prefill: args.is_prefill,
984	                is_decode: args.is_decode,
985	            }
986	        }
987	    };
988	
989	    Ok(inner)
990	}
991	
992	#[pyfunction]
993	#[pyo3(signature = (distributed_runtime, input, engine_config, frontend_route_extensions=None))]
994	pub fn run_input<'p>(
995	    py: Python<'p>,
996	    distributed_runtime: super::DistributedRuntime,
997	    input: &str,
998	    engine_config: EngineConfig,
999	    frontend_route_extensions: Option<PyObject>,
1000	) -> PyResult<Bound<'p, PyAny>> {
1001	    let input_enum: Input = input.parse().map_err(to_pyerr)?;
1002	    let frontend_route_extensions =
1003	        super::frontend_routes::frontend_route_extensions_from_py(py, frontend_route_extensions)?;
1004	    let worker_selection_policy_factory = crate::worker_selection_policy_factory(
1005	        &engine_config
1006	            .inner
1007	            .local_model()
1008	            .router_config()
1009	            .kv_router_config,
1010	    )
1011	    .map_err(to_pyerr)?;
1012	    if worker_selection_policy_factory.is_some()
1013	        && !engine_config
1014	            .inner
1015	            .local_model()
1016	            .router_config()
1017	            .router_mode
1018	            .is_kv_routing()
1019	    {
1020	        return Err(PyValueError::new_err(
1021	            "linked worker-selection policies require --router-mode kv",
1022	        ));
1023	    }
1024	    if worker_selection_policy_factory.is_some() && !matches!(&input_enum, Input::Http) {
1025	        return Err(PyValueError::new_err(
1026	            "linked worker-selection policies require HTTP frontend input",
1027	        ));
1028	    }
1029	    pyo3_async_runtimes::tokio::future_into_py(py, async move {
1030	        if let Some(factory) = worker_selection_policy_factory {
1031	            HttpFrontend::default()
1032	                .frontend_route_extensions(frontend_route_extensions)
1033	                .worker_selection_policy_factory(move |config, worker_type, partition| {
1034	                    factory(config, worker_type, partition)
1035	                })
1036	                .run(distributed_runtime.inner.clone(), engine_config.inner)
1037	                .await
1038	                .map_err(to_pyerr)?;
1039	            return Ok(());
1040	        }
1041	        dynamo_llm::entrypoint::input::run_input_with_frontend_route_extensions(
1042	            distributed_runtime.inner.clone(),
1043	            input_enum,
1044	            engine_config.inner,
1045	            frontend_route_extensions,
1046	        )
1047	        .await
1048	        .map_err(to_pyerr)?;
1049	        Ok(())
1050	    })
1051	}
1052	
1053	pub fn to_pyerr<E>(err: E) -> PyErr
1054	where
1055	    E: Display,
1056	{
1057	    PyException::new_err(format!("{}", err))
1058	}
