71	    client: &Client,
72	    min_initial_workers: usize,
73	) -> anyhow::Result<()> {
74	    if min_initial_workers == 0 {
75	        return Ok(());
76	    }
77	
78	    if min_initial_workers == 1 {
79	        client.wait_for_instances().await?;
80	        return Ok(());
81	    }
82	
83	    let mut watcher = client.instance_avail_watcher();
84	    loop {
85	        let available = watcher.borrow_and_update().len();
86	        if available >= min_initial_workers {
87	            return Ok(());
88	        }
89	
90	        tokio::time::timeout(Duration::from_secs(120), watcher.changed())
91	            .await
92	            .map_err(|_| {
93	                anyhow::anyhow!(
94	                    "timed out waiting for {} initial workers for endpoint {}",
95	                    min_initial_workers,
96	                    client.endpoint.id()
97	                )
98	            })?
99	            .map_err(|_| {
100	                anyhow::anyhow!(
101	                    "instance watcher closed before {} workers appeared for endpoint {}",
102	                    min_initial_workers,
103	                    client.endpoint.id()
104	                )
105	            })?;
