127	/// LoRA-aware routing is only implemented for the KV, Random, and RoundRobin modes. `Direct`
128	/// dispatches to a caller-chosen worker and bypasses both the LoRA filter and non-KV load
129	/// tracking; the advanced load-based modes (`PowerOfTwoChoices`, `LeastLoaded`,
130	/// `DeviceAwareWeighted`) have no 2-stage LoRA filtering. Reject those combinations so a
131	/// misconfiguration fails fast — at startup, before the initial-worker wait — instead of
132	/// silently mis-routing adapter traffic to a worker without the adapter.
133	fn validate_router_mode_for_lora(
134	    router_mode: RouterMode,
135	    lora_enabled: bool,
136	    session_affinity_enabled: bool,
137	) -> anyhow::Result<()> {
138	    if !lora_enabled {
139	        return Ok(());
140	    }
141	    if session_affinity_enabled
142	        && matches!(router_mode, RouterMode::Random | RouterMode::RoundRobin)
143	    {
144	        anyhow::bail!(
145	            "session affinity is unsupported with DYN_LORA_ENABLED and {router_mode:?} routing"
146	        );
147	    }
148	    match router_mode {
149	        RouterMode::KV | RouterMode::Random | RouterMode::RoundRobin => Ok(()),
150	        RouterMode::Direct
151	        | RouterMode::PowerOfTwoChoices
152	        | RouterMode::LeastLoaded
153	        | RouterMode::DeviceAwareWeighted => anyhow::bail!(
154	            "LoRA serving (DYN_LORA_ENABLED) is not supported with router mode {router_mode:?}; \
155	             use KV, Random, or RoundRobin for LoRA-aware routing, or disable LoRA serving."
156	        ),
157	    }
